export function resolveConsolidationDestination(rawPathname: string): string {
  let normalized = rawPathname || '/';
  if (normalized.length > 1) {
    normalized = normalized.replace(/\/+$/, '') || '/';
  }
  const exact = EXACT_CONSOLIDATION_REDIRECTS[normalized] ?? EXACT_CONSOLIDATION_REDIRECTS[normalized.toLowerCase()];
  if (exact) return exact;

  // Try URI-decoded path (e.g. %E2%80%8B legacy slugs)
  try {
    const decoded = decodeURIComponent(normalized);
    const exactDecoded = EXACT_CONSOLIDATION_REDIRECTS[decoded] ?? EXACT_CONSOLIDATION_REDIRECTS[decoded.toLowerCase()];
    if (exactDecoded) return exactDecoded;
  } catch {
    // Ignore malformed URI encoding and fall through to prefix/pattern checks
  }

  const lower = normalized.toLowerCase();
  for (const [prefix, target] of PREFIX_CONSOLIDATION_REDIRECTS) {
    if (lower === prefix || lower.startsWith(prefix + '/')) {
      return target;
    }
  }

  // Historic metro & suburb city landing page patterns -> direct Juris Digital service pages
  if (/^\/law-firm-seo-[a-z0-9-]+$/.test(lower)) {
    return 'https://jurisdigital.com/services/law-firm-seo/';
  }
  if (/^\/law-firm-website-design-[a-z0-9-]+$/.test(lower)) {
    return 'https://jurisdigital.com/services/law-firm-website-design/';
  }
  if (/^\/google-ads-(?:for-)?lawyers-[a-z0-9-]+$/.test(lower)) {
    return 'https://jurisdigital.com/services/ppc-law-firms/';
  }
  if (/^\/law-firm-marketing-[a-z0-9-]+$/.test(lower)) {
    return 'https://jurisdigital.com/services/';
  }

  // Practice area / service intersections not in exact map
  if (lower.endsWith('/law-firm-seo')) return 'https://jurisdigital.com/services/law-firm-seo/';
  if (lower.endsWith('/google-ads-for-law-firms')) return 'https://jurisdigital.com/services/ppc-law-firms/';
  if (lower.endsWith('/local-seo-for-law-firms')) return 'https://jurisdigital.com/services/local-seo-for-lawyers/';
  if (lower.endsWith('/law-firm-websites')) return 'https://jurisdigital.com/services/law-firm-website-design/';
  if (lower.endsWith('/law-firm-content-writing')) return 'https://jurisdigital.com/services/legal-content-writing/';

  return CONSOLIDATION_FALLBACK_URL;
}
